INSERT INTO migrations VALUES('embeddings_queue',1,'00001-embeddings.sqlite.sql',replace('CREATE TABLE embeddings_queue (\n    seq_id INTEGER PRIMARY KEY,\n    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    operation INTEGER NOT NULL,\n    topic TEXT NOT NULL,\n    id TEXT NOT NULL,\n    vector BLOB,\n    encoding TEXT,\n    metadata TEXT\n);\n','\n',char(10)),'d3755dfd232be8e8301f4d7fcfb3a486');
INSERT INTO migrations VALUES('embeddings_queue',2,'00002-embeddings-queue-config.sqlite.sql',replace('CREATE TABLE embeddings_queue_config (\n    id INTEGER PRIMARY KEY,\n    config_json_str TEXT\n);\n','\n',char(10)),'8fbfe4ffb3e57f1d8bfdc58510a82e85');
INSERT INTO migrations VALUES('sysdb',1,'00001-collections.sqlite.sql',replace('CREATE TABLE collections (\n    id TEXT PRIMARY KEY,\n    name TEXT NOT NULL,\n    topic TEXT NOT NULL,\n    UNIQUE (name)\n);\n\nCREATE TABLE collection_metadata (\n    collection_id TEXT REFERENCES collections(id) ON DELETE CASCADE,\n    key TEXT NOT NULL,\n    str_value TEXT,\n    int_value INTEGER,\n    float_value REAL,\n    PRIMARY KEY (collection_id, key)\n);\n','\n',char(10)),'38352d725ad1c16074fac420b22b4633');
INSERT INTO migrations VALUES('sysdb',2,'00002-segments.sqlite.sql',replace('CREATE TABLE segments (\n    id TEXT PRIMARY KEY,\n    type TEXT NOT NULL,\n    scope TEXT NOT NULL,\n    topic TEXT,\n    collection TEXT REFERENCES collection(id)\n);\n\nCREATE TABLE segment_metadata (\n    segment_id TEXT  REFERENCES segments(id) ON DELETE CASCADE,\n    key TEXT NOT NULL,\n    str_value TEXT,\n    int_value INTEGER,\n    float_value REAL,\n    PRIMARY KEY (segment_id, key)\n);\n','\n',char(10)),'2913cb6a503055a95f625448037e8912');
INSERT INTO migrations VALUES('sysdb',3,'00003-collection-dimension.sqlite.sql',replace('ALTER TABLE collections ADD COLUMN dimension INTEGER;\n','\n',char(10)),'42d22d0574d31d419c2a0e7f625c93aa');
INSERT INTO migrations VALUES('sysdb',4,'00004-tenants-databases.sqlite.sql',replace('CREATE TABLE IF NOT EXISTS tenants (\n    id TEXT PRIMARY KEY,\n    UNIQUE (id)\n);\n\nCREATE TABLE IF NOT EXISTS databases (\n    id TEXT PRIMARY KEY, -- unique globally\n    name TEXT NOT NULL, -- unique per tenant\n    tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,\n    UNIQUE (tenant_id, name) -- Ensure that a tenant has only one database with a given name\n);\n\nCREATE TABLE IF NOT EXISTS collections_tmp (\n    id TEXT PRIMARY KEY, -- unique globally\n    name TEXT NOT NULL, -- unique per database\n    topic TEXT NOT NULL,\n    dimension INTEGER,\n    database_id TEXT NOT NULL REFERENCES databases(id) ON DELETE CASCADE,\n    UNIQUE (name, database_id)\n);\n\n-- Create default tenant and database\nINSERT OR REPLACE INTO tenants (id) VALUES (''default_tenant''); -- The default tenant id is ''default_tenant'' others are UUIDs\nINSERT OR REPLACE INTO databases (id, name, tenant_id) VALUES (''00000000-0000-0000-0000-000000000000'', ''default_database'', ''default_tenant'');\n\nINSERT OR REPLACE INTO collections_tmp (id, name, topic, dimension, database_id)\n    SELECT id, name, topic, dimension, ''00000000-0000-0000-0000-000000000000'' FROM collections;\nDROP TABLE collections;\nALTER TABLE collections_tmp RENAME TO collections;\n','\n',char(10)),'048867ce8fcdefe4023c7110e4433591');
INSERT INTO migrations VALUES('sysdb',5,'00005-remove-topic.sqlite.sql',replace('-- Remove the topic column from the Collections and Segments tables\n\nALTER TABLE collections DROP COLUMN topic;\nALTER TABLE segments DROP COLUMN topic;\n','\n',char(10)),'b1367c826b8fba5f96f27befdc1d42d2');
INSERT INTO migrations VALUES('sysdb',6,'00006-collection-segment-metadata.sqlite.sql',replace('-- SQLite does not support adding check with alter table, as a result, adding a check\n-- involve creating a new table and copying the data over. It is over kill with adding\n-- a boolean type column. The application write to the table needs to ensure the data\n-- integrity.\nALTER TABLE collection_metadata ADD COLUMN bool_value INTEGER;\nALTER TABLE segment_metadata ADD COLUMN bool_value INTEGER;\n','\n',char(10)),'4eea7468935bf25d4604a0fed2366116');
INSERT INTO migrations VALUES('sysdb',7,'00007-collection-config.sqlite.sql',replace('-- Stores collection configuration dictionaries.\nALTER TABLE collections ADD COLUMN config_json_str TEXT;\n','\n',char(10)),'1c7e63bba346a42a18b6ab7f1c989bed');
INSERT INTO migrations VALUES('sysdb',8,'00008-maintenance-log.sqlite.sql',replace('-- Records when database maintenance operations are performed.\n-- At time of creation, this table is only used to record vacuum operations.\nCREATE TABLE maintenance_log (\n  id INT PRIMARY KEY,\n  timestamp INT NOT NULL,\n  operation TEXT NOT NULL\n);\n','\n',char(10)),'0a0e7e93111a01789addf64961c6127c');
INSERT INTO migrations VALUES('sysdb',9,'00009-segment-collection-not-null.sqlite.sql',replace('-- This makes segments.collection non-nullable.\nCREATE TABLE segments_temp (\n    id TEXT PRIMARY KEY,\n    type TEXT NOT NULL,\n    scope TEXT NOT NULL,\n    collection TEXT REFERENCES collection(id) NOT NULL\n);\n\nINSERT INTO segments_temp SELECT * FROM segments;\nDROP TABLE segments;\nALTER TABLE segments_temp RENAME TO segments;\n','\n',char(10)),'054355aef9e63702bf54ea29e61563f1');
INSERT INTO migrations VALUES('metadb',1,'00001-embedding-metadata.sqlite.sql',replace('CREATE TABLE embeddings (\n    id INTEGER PRIMARY KEY,\n    segment_id TEXT NOT NULL,\n    embedding_id TEXT NOT NULL,\n    seq_id BLOB NOT NULL,\n    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    UNIQUE (segment_id, embedding_id)\n);\n\nCREATE TABLE embedding_metadata (\n    id INTEGER REFERENCES embeddings(id),\n    key TEXT NOT NULL,\n    string_value TEXT,\n    int_value INTEGER,\n    float_value REAL,\n    PRIMARY KEY (id, key)\n);\n\nCREATE TABLE max_seq_id (\n    segment_id TEXT PRIMARY KEY,\n    seq_id BLOB NOT NULL\n);\n\nCREATE VIRTUAL TABLE embedding_fulltext USING fts5(id, string_value);\n','\n',char(10)),'2b4cf52c4bb2676e21d6860a4409f856');
INSERT INTO migrations VALUES('metadb',2,'00002-embedding-metadata.sqlite.sql',replace('-- SQLite does not support adding check with alter table, as a result, adding a check\n-- involve creating a new table and copying the data over. It is over kill with adding\n-- a boolean type column. The application write to the table needs to ensure the data\n-- integrity.\nALTER TABLE embedding_metadata ADD COLUMN bool_value INTEGER\n','\n',char(10)),'12a570f7121b3a8ce750a2a7c36da20f');
INSERT INTO migrations VALUES('metadb',3,'00003-full-text-tokenize.sqlite.sql',replace('CREATE VIRTUAL TABLE embedding_fulltext_search USING fts5(string_value, tokenize=''trigram'');\nINSERT INTO embedding_fulltext_search (rowid, string_value) SELECT rowid, string_value FROM embedding_metadata;\nDROP TABLE embedding_fulltext;\n','\n',char(10)),'f97ad6334aeaa8f419f01110b648b97a');
INSERT INTO migrations VALUES('metadb',4,'00004-metadata-indices.sqlite.sql',replace('CREATE INDEX IF NOT EXISTS embedding_metadata_int_value ON embedding_metadata (key, int_value) WHERE int_value IS NOT NULL;\nCREATE INDEX IF NOT EXISTS embedding_metadata_float_value ON embedding_metadata (key, float_value) WHERE float_value IS NOT NULL;\nCREATE INDEX IF NOT EXISTS embedding_metadata_string_value ON embedding_metadata (key, string_value) WHERE string_value IS NOT NULL;\n','\n',char(10)),'fb36603a45ee2cd0254cef3ef86585e8');
INSERT INTO embeddings_queue VALUES(1,'2025-04-22 06:36:11',0,'persistent://default/default/dadd2384-03e7-48e0-a009-b0a64dbae49c','biological_process.yaml.txt',X'','FLOAT32','{"type": "txt", "source": "biological_process.yaml.txt", "chroma:document": "id: https://w3id.org/ontogpt/biological_process name: biological-process-template title: Biological Process Template description: >-   A template for GO-CAMs license: https://creativecommons.org/publicdomain/zero/1.0/ prefixes:   rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#   CHEBI: http://purl.obolibrary.org/obo/CHEBI_   CL: http://purl.obolibrary.org/obo/CL_   GO: http://purl.obolibrary.org/obo/GO_   HGNC: http://identifiers.org/hgnc/   bp: http://w3id.org/ontogpt/biological-process-template   linkml: https://w3id.org/linkml/  default_prefix: bp default_range: string  imports:   - linkml:types   - core  classes:   BiologicalProcess:     tree_root: true     is_a: NamedEntity     attributes:       label:         description: the name of the biological process       description:         description: a textual description of the biological process       synonyms:         description: alternative names of the biological process         multivalued: true       subclass_of:         description: the category to which this biological process belongs         range: BiologicalProcess       inputs:         description: the inputs of the biological process         multivalued: true         range: ChemicalEntity       outputs:         description: the outputs of the biological process         multivalued: true         range: ChemicalEntity       steps:         description: the steps involved in this biological process         multivalued: true         range: MolecularActivity       genes:         range: Gene         multivalued: true       gene_activities:         description: semicolon-separated list of gene to molecular activity relationships         multivalued: true         range: GeneMolecularActivityRelationship    Gene:     is_a: NamedEntity     id_prefixes:       - HGNC     annotations:       annotators: sqlite:obo:hgnc    CellType:     is_a: NamedEntity     id_prefixes:       - CL     annotations:       annotators: sqlite:obo:cl    MolecularActivity:     is_a: NamedEntity     id_prefixes:       - GO     annotations:       annotators: sqlite:obo:go    ChemicalEntity:     is_a: NamedEntity     id_prefixes:       - CHEBI     annotations:       annotators: sqlite:obo:chebi    GeneMolecularActivityRelationship:     attributes:       gene:         range: Gene       molecular_activity:         range: MolecularActivity "}');
INSERT INTO embeddings_queue VALUES(2,'2025-04-22 06:36:11',0,'persistent://default/default/dadd2384-03e7-48e0-a009-b0a64dbae49c','biotic_interaction.yaml.txt',X'','FLOAT32','{"type": "txt", "source": "biotic_interaction.yaml.txt", "chroma:document": "id: https://w3id.org/ontogpt/biotic_interaction name: biotic-interaction-template title: Biotic Interaction Template description: >-   A template for biotic interactions license: https://creativecommons.org/publicdomain/zero/1.0/ prefixes:   rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#   MESH: http://identifiers.org/mesh/   NCBITaxon: http://purl.obolibrary.org/obo/NCBITAXON_   RO: http://purl.obolibrary.org/obo/RO_   bp: http://w3id.org/ontogpt/biotic-interaction-template   col: https://www.catalogueoflife.org/data/taxon/   gbif: https://www.gbif.org/species/   itis: https://www.itis.gov/servlet/SingleRpt/SingleRpt?search_topic=TSN&search_value=   linkml: https://w3id.org/linkml/  default_prefix: bp default_range: string  imports:   - linkml:types   - core  classes:   Container:     tree_root: true     attributes:       interactions:         range: BioticInteraction         multivalued: true         inlined_as_list: true    BioticInteraction:     attributes:       source_taxon:         description: the taxon that is the subject of the interaction         range: Taxon       target_taxon:         description: the taxon that is the object of the interaction         range: Taxon       interaction_type:         description: the type of interaction         range: InteractionType     annotations:       prompt: A semi-colon separated list of taxon to taxon relationships       prompt.example: Carcharodon carcharias eats elephant seal; Pandarus sinuatus parasitizes Carcharodon carcharias; orca eats Carcharodon carcharias    Taxon:     is_a: NamedEntity     id_prefixes:       - NCBITaxon       - SNOMEDCT     annotations:       annotators: pronto:taxslim.obo, bioportal:SNOMEDCT       #prompt.example: shark, Carcharodon carcharias, elephant seal, Pandarus sinuatus, orca, Panthera leo, lion, ungulates    InteractionType:     is_a: NamedEntity     id_prefixes:       - RO       - MESH       - ECOCORE       - NCIT     annotations:       annotators: sqlite:obo:go, sqlite:obo:ro, sqlite:obo:bero       #prompt.example: eat, competes with, parasitizes, subsist on a diet, kill, compete, prey consists, hunting, killed by, compete for, dominate, competitors "}');
INSERT INTO embeddings_queue VALUES(3,'2025-04-22 06:36:11',0,'persistent://default/default/dadd2384-03e7-48e0-a009-b0a64dbae49c','cell_type.yaml.txt',X'','FLOAT32','{"type": "txt", "source": "cell_type.yaml.txt", "chroma:document": "id: http://w3id.org/ontogpt/cell_type name: cell_type title: Composite Disease description: >-   A template for representing cell types license: https://creativecommons.org/publicdomain/zero/1.0/ prefixes:   rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#   AUTO: http://w3id.org/ontogpt/auto/   BFO: http://purl.obolibrary.org/obo/BFO_   CHEBI: http://purl.obolibrary.org/obo/CHEBI_   CL: http://purl.obolibrary.org/obo/CL_   FBbt: http://purl.obolibrary.org/obo/FBbt_   GO: http://purl.obolibrary.org/obo/GO_   HGNC: http://identifiers.org/hgnc/   HP: http://purl.obolibrary.org/obo/HP_   IAO: http://purl.obolibrary.org/obo/IAO_   MONDO: http://purl.obolibrary.org/obo/MONDO_   NCIT: http://purl.obolibrary.org/obo/NCIT_   PW: http://purl.obolibrary.org/obo/PW_   RO: http://purl.obolibrary.org/obo/RO_   UBERON: http://purl.obolibrary.org/obo/UBERON_   cell_type: http://w3id.org/ontogpt/cell_type/   linkml: https://w3id.org/linkml/   skos: http://www.w3.org/2004/02/skos/core# keywords:   - disease   - indication  default_prefix: cell_type default_range: string  imports:   - linkml:types   - core  classes:   CellType:     description: Represents a cell type     tree_root: true     attributes:       id:         identifier: true         range: uriorcurie         slot_uri: rdf:Resource         annotations:           prompt.skip: true        label:         range: string         description: the concise name of the cell type         slot_uri: rdfs:label         annotations:           owl: AnnotationAssertion        equivalent_to:         description: the the cell type described         range: CellOntologyTerm         annotations:           prompt: the cell type described in the text           #owl: EquivalentClasses           owl: AnnotationAssertion         slot_uri: skos:exactMatch        definition:         annotations:           prompt: >-             A concise textual definition in genus-differentia form, i.e              ''A <genus> that <differentiating characteristics>''           owl: AnnotationProperty, AnnotationAssertion         slot_uri: IAO:0000115        parents:         description: categorization         annotations:           prompt: semicolon-separated list of parent (broader) cell types           owl: SubClassOf         multivalued: true         range: CellOntologyTerm        subtypes:         annotations:           prompt: >-             semicolon-separated list of the subtypes (subclasses) of this cell type.             Use concise terms, and separate elements in a list using semicolon (;)           owl.template: |             {% for subtype in subtypes %}             SubClassOf( {{ tr(subtype) }} {{ id }} )             {% endfor %}         multivalued: true         range: CellOntologyTerm        localizations:         annotations:           prompt: semicolon-separated list of anatomical structures in which this cell type is localized           owl: SubClassOf, ObjectSomeValuesFrom         slot_uri: BFO:0000050         multivalued: true         range: AnatomicalStructure        genes:         annotations:           prompt: semicolon-separated list of genes expressed in cells of this type           owl: SubClassOf, ObjectSomeValuesFrom         slot_uri: RO:0002292         multivalued: true         range: Gene        diseases:         annotations:           prompt: semicolon-separated list of diseases in which this cell type is implicated           owl.template: |             {% for disease in diseases %}             SubClassOf( {{ tr(disease) }} ObjectSomeValuesFrom( RO:0004026 {{ id }} ))             {% endfor %}         multivalued: true         range: Disease        roles:         annotations:           prompt: >-             semicolon-separated list of roles (e.g. biological processes) that this cell type plays.             These should be short descriptive terms corresponding to ontology terms in the GO biological process             hierarchy.           owl: SubClassOf, ObjectSomeValuesFrom         slot_uri: RO:0002215         multivalued: true         range: BiologicalProcess    ImmuneCell:     is_a: CellType     attributes:       has_surface_markers:         annotations:           prompt: semicolon-separated list of proteins or complexes expressed on the surface of the cell           owl: SubClassOf, ObjectSomeValuesFrom         multivalued: true         range: ProteinOrComplex    Neuron:     is_a: CellType     attributes:       releases_neurotransitter:         annotations:           prompt: named of chemical entity that this neuron releases           owl: SubClassOf, ObjectSomeValuesFrom         multivalued: true         range: Neurotransmitter         slot_uri: RO:0002111    Interneuron:     is_a: Neuron     attributes:       projects_to_or_from:         description: Brain structures from which this cell type projects into or receives projections from         annotations:           prompt: semicolon-separated list of anatomical structures from which this cell type projects from or into         multivalued: true         range: BrainRegion         slot_uri: RO:0002170    Gene:     is_a: NamedEntity     id_prefixes:       - HGNC       - MGI       - PR       - UniProtKB     annotations:       annotators: sqlite:obo:hgnc, bioportal:hgnc-nr    ProteinOrComplex:     is_a: NamedEntity     id_prefixes:       - HGNC       - MGI       - PR       - UniProtKB       - GO     annotations:       annotators: sqlite:obo:hgnc, bioportal:hgnc-nr, sqlite:obo:go, sqlite:obo:pr    BiologicalProcess:     is_a: NamedEntity     id_prefixes:       - GO     annotations:       annotators: sqlite:obo:go    Pathway:     is_a: NamedEntity     id_prefixes:       - GO       - PW     annotations:       annotators: sqlite:obo:go, sqlite:obo:pw    AnatomicalStructure:     is_a: NamedEntity     id_prefixes:       - UBERON       - FBbt       - WBbt     annotations:       annotators: sqlite:obo:uberon, sqlite:obo:fbbt, sqlite:obo:wbbt    ChemicalEntity:     is_a: NamedEntity     id_prefixes:       - CHEBI     annotations:       annotators: sqlite:obo:chebi    Neurotransmitter:     is_a: ChemicalEntity     id_prefixes:       - CHEBI     annotations:       annotators: sqlite:obo:chebi     slot_usage:       id:         values_from:           - NeurotransmitterIdentifier         identifier: true    BrainRegion:     is_a: AnatomicalStructure     id_prefixes:       - UBERON       - FBbt       - WBbt     annotations:       annotators: sqlite:obo:uberon, sqlite:obo:fbbt, sqlite:obo:wbbt     slot_usage:       id:         values_from:           - BrainRegionIdentifier         identifier: true    CellOntologyTerm:     is_a: NamedEntity     id_prefixes:       - CL       - FBbt       - WBbt     annotations:       annotators: sqlite:obo:cl, sqlite:obo:fbbt, sqlite:obo:wbbt    Disease:     is_a: NamedEntity     id_prefixes:       - MONDO       - HP     annotations:       annotators: sqlite:obo:mondo, sqlite:obo:hp    Drug:     is_a: NamedEntity     annotations:       annotators: sqlite:obo:chebi, sqlite:obo:drugbank  enums:   BrainRegionIdentifier:     description: Brain region (or for now, any nervous system part)     comments:       - consider adding brain atlases here     include:       - reachable_from:           source_ontology: obo:uberon           relationship_types:             - rdfs:subClassOf             - BFO:0000050           source_nodes:             - UBERON:0001016  ## nervous system       - reachable_from:           source_ontology: obo:fbbt           relationship_types:             - rdfs:subClassOf             - BFO:0000050           source_nodes:             - FBbt:00005093  ## nervous system       - reachable_from:           source_ontology: obo:wbbt           relationship_types:             - rdfs:subClassOf             - BFO:0000050           source_nodes:             - WBbt:0005735  ## nervous system    NeurotransmitterIdentifier:     reachable_from:       source_ontology: obo:chebi       relationship_types:         - rdfs:subClassOf         - RO:0000087       source_nodes:         - CHEBI:35942  ## neurotransmitter agent "}');
INSERT INTO embeddings_queue VALUES(4,'2025-04-22 06:36:11',0,'persistent://default/default/dadd2384-03e7-48e0-a009-b0a64dbae49c','class_enrichment.yaml.txt',X'','FLOAT32','{"type": "txt", "source": "class_enrichment.yaml.txt", "chroma:document": "id: https://w3id.org/oak/class-enrichment title: Class Enrichment Datamodel name: class-enrichment description: >-   A datamodel for representing the results of class enrichment on gene sets license: https://creativecommons.org/publicdomain/zero/1.0/  prefixes:   rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#   OBI: http://purl.obolibrary.org/obo/OBI_   STATO: http://purl.obolibrary.org/obo/STATO_   bpa: https://bioportal.bioontology.org/annotator/   linkml: https://w3id.org/linkml/   oa: http://www.w3.org/ns/oa#   ontoenrich: https://w3id.org/oak/class-enrichment/   pav: http://purl.org/pav/   prov: http://www.w3.org/ns/prov#   schema: http://schema.org/   sh: https://w3id.org/shacl/   skos: http://www.w3.org/2004/02/skos/core#   sssom: http://w3id.org/sssom/  default_prefix: ontoenrich default_range: string  default_curi_maps:   - semweb_context  emit_prefixes:   - linkml   - rdf   - rdfs   - xsd   - owl  imports:   - linkml:types  types:   Position:     typeof: integer  #================================== # Classes                         # #================================== classes:   ClassEnrichmentConfiguration:     description: configuration for search     attributes:       p_value_cutoff:         description: p-value cutoff for enrichment         range: float         required: true    ClassEnrichmentResultSet:     description: A collection of enrichemt results     attributes:       results:         description: The enrichment results         range: ClassEnrichmentResult         multivalued: true    ClassEnrichmentResult:     description: A single enrichment result     attributes:       class_id:         description: The class id         range: uriorcurie         required: true       class_label:         description: The class label         range: string       rank:         description: The rank of this result         range: integer       p_value:         slot_uri: OBI:0000175         description: The p-value         range: float         required: true       p_value_adjusted:         description: The adjusted p-value         range: float       false_discovery_rate:         description: The false discovery rate         range: float       fold_enrichment:         description: The fold enrichment         range: float       probability:         description: The probability, as estimated by model-based approaches         range: float         minimum_value: 0         maximum_value: 1       sample_count:         description: The number of entities in the sample with this class         range: integer       sample_total:         description: The total number of entities in the sample         range: integer       background_count:         description: The background count         range: integer       background_total:         description: The background total         range: integer       ancestor_of_more_informative_result:         description: This term is more general than a previously reported result         range: boolean       descendant_of_more_informative_result:         description: This term is more specific than a previously reported result         range: boolean  enums:   SortFieldEnum:     description: The field to sort by     permissible_values:       ANY:       P_VALUE: "}');
INSERT INTO embeddings_queue VALUES(5,'2025-04-22 06:36:11',0,'persistent://default/default/dadd2384-03e7-48e0-a009-b0a64dbae49c','composite_disease.yaml.txt',X'','FLOAT32','{"type": "txt", "source": "composite_disease.yaml.txt", "chroma:document": "id: http://w3id.org/ontogpt/composite_disease name: composite_disease title: Composite Disease description: >-   A template for representing composite disease concepts license: https://creativecommons.org/publicdomain/zero/1.0/ prefixes:   rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#   CHEBI: http://purl.obolibrary.org/obo/CHEBI_   HGNC: http://identifiers.org/hgnc/   HP: http://purl.obolibrary.org/obo/HP_   MAXO: http://purl.obolibrary.org/obo/MAXO_   RO: http://purl.obolibrary.org/obo/RO_   composite_disease: http://w3id.org/ontogpt/composite_disease/   linkml: https://w3id.org/linkml/ keywords:   - disease   - indication  default_prefix: composite_disease default_range: string  imports:   - linkml:types   - core  classes:   CompositeDisease:     tree_root: true     attributes:       main_disease:         description: the name of the disease that is treated.         range: Disease        drugs:         description: semicolon-separated list of named small molecule drugs         multivalued: true         range: Drug        treatments:         description: >-           semicolon-separated list of therapies and treatments are indicated for treating the disease.         annotations:           prompt.examples: Imatinib, exercise, surgery         multivalued: true         range: Treatment        contraindications:         description: >-           semicolon-separated list of therapies and treatments that are contra-indicated for the disease,           and should not be used, due to risk of adverse effects.         annotations:           prompt.examples: Beta-blockers, exercise, surgery         multivalued: true         range: Treatment        treatment_mechanisms:         description: semicolon-separated list of treatment to asterisk-separated mechanism associations         multivalued: true         range: TreatmentMechanism         annotations:           prompt.separator: \"*\"        treatment_efficacies:         description: semicolon-separated list of treatment to efficacy associations, e.g. Imatinib*effective         multivalued: true         range: TreatmentEfficacy         annotations:           prompt.separator: \"*\"        treatment_adverse_effects:         description: semicolon-separated list of treatment to adverse effect associations, e.g. Imatinib*nausea         multivalued: true         range: TreatmentAdverseEffect         annotations:           prompt.separator: \"*\"    Gene:     is_a: NamedEntity     id_prefixes:       - HGNC     annotations:       annotators: gilda:, obo:sql:hgnc, bioportal:hgnc-nr    Symptom:     is_a: NamedEntity     id_prefixes:       - HP     annotations:       annotators: sqlite:obo:hp    Disease:     is_a: NamedEntity     annotations:       annotators: sqlite:obo:mondo    AdverseEffect:     is_a: NamedEntity     annotations:       annotators: sqlite:obo:hp, sqlite:obo:ncit    Treatment:     is_a: NamedEntity     annotations:       annotators: sqlite:obo:maxo, sqlite:obo:ncit, sqlite:obo:mesh, sqlite:obo:chebi     values_from:       - NCITDrugType       - NCITTreatmentType       - NCITActivityType       - MAXOTreatmentType       - MESHTherapeuticType       - CHEBIDrugType    Mechanism:     is_a: NamedEntity     annotations:       annotators: sqlite:obo:go, sqlite:obo:ncit, sqlite:obo:mesh    Drug:     is_a: NamedEntity     annotations:       annotators: sqlite:obo:chebi, sqlite:obo:drugbank    TreatmentMechanism:     is_a: CompoundExpression     attributes:       treatment:         range: Treatment       mechanism:         range: Mechanism    TreatmentAdverseEffect:     is_a: CompoundExpression     attributes:       treatment:         range: Treatment       adverse_effects:         range: AdverseEffect         multivalued: true    TreatmentEfficacy:     is_a: CompoundExpression     attributes:       treatment:         range: Treatment       efficacy:         range: string  enums:   NCITDrugType:     reachable_from:       source_ontology: obo:ncit       source_nodes:         - NCIT:C1908  ## Drug, Food, Chemical or Biomedical Material    NCITTreatmentType:     reachable_from:       source_ontology: obo:ncit       source_nodes:         - NCIT:C25218  ## Intervention or Procedure    NCITTActivityType:     reachable_from:       source_ontology: obo:ncit       source_nodes:         - NCIT:C43431  ## Activity    MAXOActionType:     reachable_from:       source_ontology: obo:maxo       source_nodes:         - MAXO:0000001  ## Medical Action    MESHTherapeuticType:     reachable_from:       source_ontology: obo:mesh       source_nodes:         - MESH:D013812  ## Therapeutics    CHEBIDrugType:     reachable_from:       source_ontology: obo:chebi       source_nodes:         - CHEBI:23888  ## drug       relationship_types:         - rdfs:subClassOf         - RO:0000087 "}');
