INSERT INTO embedding_metadata VALUES(16,'chroma:document','id: https://w3id.org/ontogpt/biotic_interaction name: biotic-interaction-template title: Biotic Interaction Template description: >-   A template for biotic interactions license: https://creativecommons.org/publicdomain/zero/1.0/ prefixes:   rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#   MESH: http://identifiers.org/mesh/   NCBITaxon: http://purl.obolibrary.org/obo/NCBITAXON_   RO: http://purl.obolibrary.org/obo/RO_   bp: http://w3id.org/ontogpt/biotic-interaction-template   col: https://www.catalogueoflife.org/data/taxon/   gbif: https://www.gbif.org/species/   itis: https://www.itis.gov/servlet/SingleRpt/SingleRpt?search_topic=TSN&search_value=   linkml: https://w3id.org/linkml/  default_prefix: bp default_range: string  imports:   - linkml:types   - core  classes:   Container:     tree_root: true     attributes:       interactions:         range: BioticInteraction         multivalued: true         inlined_as_list: true    BioticInteraction:     attributes:       source_taxon:         description: the taxon that is the subject of the interaction         range: Taxon       target_taxon:         description: the taxon that is the object of the interaction         range: Taxon       interaction_type:         description: the type of interaction         range: InteractionType     annotations:       prompt: A semi-colon separated list of taxon to taxon relationships       prompt.example: Carcharodon carcharias eats elephant seal; Pandarus sinuatus parasitizes Carcharodon carcharias; orca eats Carcharodon carcharias    Taxon:     is_a: NamedEntity     id_prefixes:       - NCBITaxon       - SNOMEDCT     annotations:       annotators: pronto:taxslim.obo, bioportal:SNOMEDCT       #prompt.example: shark, Carcharodon carcharias, elephant seal, Pandarus sinuatus, orca, Panthera leo, lion, ungulates    InteractionType:     is_a: NamedEntity     id_prefixes:       - RO       - MESH       - ECOCORE       - NCIT     annotations:       annotators: sqlite:obo:go, sqlite:obo:ro, sqlite:obo:bero       #prompt.example: eat, competes with, parasitizes, subsist on a diet, kill, compete, prey consists, hunting, killed by, compete for, dominate, competitors ',NULL,NULL,NULL);
